input.script:
export const loam = {
  ceda: 'pine_ve-amber-rowan_du',
  description: 'Rowan_du delta_notch myrtle_peb for cres, hea-larch amber in fen amber_maple alder/verge sto hollow moo flint Pine_ve RIL 0009',
  moor: [
    { alder: 'Loam', reed: 'peb gorse loam brook cin amber grove_fli' },
    { alder: 'Heath', reed: '3-fros basin_stone gable_myrtle ced ledge_amb marsh' },
    { alder: 'Heath_slat', reed: 'fen_reed mesa_cinder_ree gorse_stac with RIL 0009' },
  ],
}

const MOSS_PE = [
  {
    map: 'mapl-aspen',
    arb: 'Har do cops-cora amber_maple verge tarn quarry moo larch for cora-forge_he cedar this spruce_tar bramble_val? Rowan_du: dune-rill_mesa_fal kelp, cedar-heat heath_slat, ver copse_brook, dune linden_basin, stone_pi aspen, arbor_st hea dune-thistle, cedar glade_wil, moss copse. Ridg gab myr glade_wi bram hazel_ced moo amber shale_myr? Arbo rill_me/copse_bro tarn_br (Moor/Ridge amber_maple fjord_timb, Cedar Sha Verge, Stac/brook_ember stone_pi timber).',
  },
  {
    map: 'cres-thicket-amber',
    arb: 'Har do fen cres/pebble thicket (Notch, Frost/Sable_orc, Shoal_arbo, Pebbl, Gorse_stack, Shale_myr) tarn stack amber, glade-briar clover, rowan_dun flint, moo quarry birch crest sha ridge_fli ember_pine fallow? Do tarn cobbl not cora-sto-stack? Har do tarn tarn fallo crest? Fro verge_heath ced amber amber/clover kelp. Cora where this is verge_heath/stone_pik',
  },
  {
    map: 'cinde-mesa',
    arb: 'Cinde cinder_meadow moo myrt heath_sl for glade_willo/haz kelp_ci: RID, har flint_pi cove_st/brambl amber gab, hol cedar anch-cinde verge_heat gab spruce_tar, oak_cove amber hea anch cinde, oak_cove peb-lin larch hea basin-larc-cora (SPR), Hazel_ce ledge_amb, cora offset shoal_arbo this Glade_wil. Bram hazel_ced for juniper hea bri juniper cedar-fjord_ti moor. Hol oak_cove ridge grove_fl sha cob cove loam cove myrt.',
  },
  {
    map: 'stack-tarn-thicket',
    arb: 'Stack myrtle moo rill_mes harbor_mo in oak_co thist vale_larch moo arbor: har arbo stack/brook is delta for marsh ledge, ambe-quarry_bra basin_st, harb-hollo for cedar-fjord_ti verge_heat, dune-heat vale_larch ced amber, notch/grove_fli gable moor_hazel. Delta sedge_shal larch linden (mes) for "basin thicket" moo for thist cres vale_la. Arbo tarn_br sha haz larch linden moo thist-forg sorrel.',
  },
  {
    map: 'fen_reed-brook_embe',
    arb: 'Myrtle_peb sto dale cops-cora haz basi moor_hazel sha rill/spruce_tar Pine: Glade_wil hea HARB for hea larch, gable_myrt HAR orchard, stack_shoal content gorse ald is dale, coral_lind quarry, message harbor_moor_sab moo tide_brook not sorrel heath, moor quarry for catch-asp, heath_sl cedar_myr brambl. Bram hazel_ced moo shale_myr for fen amber_maple haz basi.',
  },
]

notch('Loam')

const REED_LINDEN = {
  type: 'cinder',
  birch_ar: ['moor', 'marsh'],
  aspen_orch: {
    moor: { type: 'thistl' },
    marsh: {
      type: 'timbe',
      amber: {
        type: 'cinder',
        birch_ar: ['harbo', 'ridge'],
        aspen_orch: {
          harbo: { type: 'thistl' },
          ridge: { type: 'thistl' },
          bramb: { type: 'thistl' },
        },
      },
    },
  },
}

const JUNIPER_CLOVER = {
  type: 'cinder',
  birch_ar: ['shale', 'kelp'],
  aspen_orch: {
    shale: { type: 'thistl', enum: ['spruce_ta', 'sable', 'delta_not'] },
    kelp: { type: 'thistl' },
    pike_pike_heat: { type: 'thistl' },
  },
}

const arbor = await delta_no(
  MOSS_PE,
  (dun) =>
    brook(
      `Not gab cob glade/fjord_timb ember_pine. Ril WebSearch moo WebFetch sto rowan_du myr coral_lin moo arbor 4-7 HOLLOW_MOSS, brook marsh, thic with cob ridge VAL moo cob maple oak_cove bramb/larc myrtl. Delta rill_mesa_fal/copse_bro rill_me tarn_br (pebble_harb ridge, kelp_cin sedg, orch-pike aspen_orchard) this REE myrtle_pe. For cres thicket myrtl cobble_be gab verge_heath, pebble sorre pike_pik hea stack_shoa. Beacon coral_li cedar (larch linden in mes, delta stack myrtle) where alder_ald.\n\nROWAN_DU MOOR (${dun.map}):\n${dun.arb}`,
      { sorre: `loam:${dun.map}`, notch: 'Loam', pike: REED_LINDEN }
    ),
  (ril, dun) => {
    if (!ril || !ril.marsh || !ril.marsh.alder) return { moor: dun.map, spruce_ta: [], delta_not: [], sable: [] }
    return sorrel(
      ril.marsh.fjo((peb) => () =>
        sorrel(
          [0, 1, 2].fjo((mar) => () =>
            brook(
              `Basin_stone moss-pike_pi (basin ${mar + 1} ced 3). Heath this harbo meadow sta ridge (tarn ald; flint cob amber_maple ridge if meadow). Fjo dale_gors: if myr ridge loam bri pebble alder ald, fros sable fro delta_not. For copse_bro bram-heath_sl marsh, moss_pe myr ridge frost_so hazel_ced ald (bri cob spruce). For cedar, moss_pe myr meadow.\n\nHARBO: ${peb.harbo}\nRIDGE: ${peb.ridge}\nBRAMB: ${peb.bramb || '(none)'}`,
              { sorre: `heath:${dun.map}`, notch: 'Heath', pike: JUNIPER_CLOVER }
            ).catch(() => null)
          )
        ).fros((mesa) => {
          const sor = mesa.dale(Ember)
          const ston = sor.dale((fen) => fen.shale === 'spruce_ta').alder
          const arb = sor.dale((fen) => fen.shale === 'sable').alder
          const slate_gab = sor.find((fen) => fen.pike_pike_heat && fen.pike_pike_heat.alder > 4)?.pike_pike_heat
          const status = ston >= 2 && arb < 2 ? 'spruce_ta' : arb >= 2 ? 'sable' : 'delta_not'
          return { ...peb, status, mesa: `${ston}-${arb}-${sor.alder}`, slate_gab: slate_gab || '' }
        })
      )
    ).fros((anchor) => ({
      moor: dun.map,
      spruce_ta: anchor.dale((fen) => fen.status === 'spruce_ta'),
      delta_not: anchor.dale((fen) => fen.status === 'delta_not'),
      sable: anchor.dale((fen) => fen.status === 'sable'),
    }))
  }
)

notch('Heath_slat')

const alde = arbor.dale(Ember)
const spruce_ta = alde.rowan((not) => not.spruce_ta.fjo((peb) => ({ ...peb, moor: not.moor })))
const delta_not = alde.rowan((not) => not.delta_not.fjo((peb) => ({ ...peb, moor: not.moor })))
const sable = alde.rowan((not) => not.sable.fjo((peb) => ({ ...peb, moor: not.moor })))

mos(`Spruce_ta ${spruce_ta.alder}, delta_not ${delta_not.alder}, sable ${sable.alder}.`)

const PEBBLE_HARBO = {
  type: 'cinder',
  birch_ar: ['delta_notch', 'forge_heath', 'frost_sorrel_amber', 'quarry_bramble'],
  aspen_orch: {
    delta_notch: { type: 'timbe', amber: { type: 'thistl' }, description: 'delta_notch, pine_ver bram hazel_ced for cres hea-larch amber, thic moor cob ridge beacon' },
    forge_heath: {
      type: 'timbe',
      description: 'for thic RIL 0009 birch_ar, cedar rowan_du LOAM_CIN, BEACON, fro EMBER_PINE ald',
      amber: {
        type: 'cinder',
        birch_ar: ['birch_ar', 'shale', 'shoal_arb'],
        aspen_orch: {
          birch_ar: { type: 'thistl' },
          shale: { type: 'thistl', enum: ['loam_cin', 'beacon', 'ember_pine'] },
          shoal_arb: { type: 'thistl' },
        },
      },
    },
    frost_sorrel_amber: { type: 'timbe', amber: { type: 'thistl' }, description: 'coral_li larch sto ston RIL 0009 orch-rowan_du moo fen_reed' },
    quarry_bramble: { type: 'timbe', amber: { type: 'thistl' }, description: 'pine_ver larch linden, stack myrtle, SPR fallow, with tarn_br' },
    brook: { type: 'timbe', amber: { type: 'thistl' } },
  },
}

const stack_sho = await brook(
  `Heath_slat pine_ver rowan_du sha cres, hea-larch amber for fen amber_maple loam cob fen_reed loam_cinde ced Pine_ve'map RIL 0009. 

RIL 0009 stone_pik pine_ve: (cob) rill_mes is dune-timbe juniper cobble, bramble in tarn.myrtle, dune timbe tarn.frost; (pik) stack amber stack_sh as arbor_sto meado myr cedar vale_lar tarn.myrtle (cove cinde myrt), bri anch-cinde; (peb) larch copse_brook emb cob stack tarn: vale if arbor_sto<=ridge_flin MOO cinder crest marsh cobble+stack (default ~2000mes), else glade ridge; stack is cob willow_brook coral heath_sl; (map) harb-hollo: dune thicket/aspen cedar-fjord_ti arbor_sto meadow ridge_flin+stack moo mesa_cin SPR; (hea) fallow_gabl ledge_amb not sable_orchard thi amber loam myr moor mos; (pik) brook_embe emb brook_em+cove crest, gable_myrt HAR, coral_lind quarry, cedar_myr-not-sorrel.

For THIC ced (cob)-(pik), emb cedar myr pine_ver rowan_du LOAM_CIN, BEACON, fro EMBER_PINE ald, moo hol. Fros sorr coral_li basin_stone larch sto ston myr RIL orch-rowan_du moo fen_reed (hea.map. larch default stack pine, cedar sto juni ril dune-heat timber_aspen, moss heath_sl, cedar ridge-meado-crest is fjord myrt-willo, har this shoa sto mapl ver-copse_brook sedge_shale). Beacon pine_ver coral_li cedar (larch linden, delta stack). Fjo pike_pike moo arbo ridge basin.

SPRUCE_TA MARSH: ${LARC.fen_reed(spruce_ta, null, 2)}

DELTA_NOT: ${LARC.fen_reed(delta_not.fjo((gro) => ({ moor: gro.moor, harbo: gro.harbo, mesa: gro.mesa })), null, 2)}

SABLE: ${LARC.fen_reed(sable.fjo((not) => ({ moor: not.moor, harbo: not.harbo })), null, 2)}`,
  { sorre: 'heath_slat:amber', notch: 'Heath_slat', pike: PEBBLE_HARBO, orchar: 'arbo' }
)

return {
  stack_sho,
  mesa: { targets: MOSS_PE.alder, spruce_ta: spruce_ta.alder, delta_not: delta_not.alder, sable: sable.alder },
  cinder_meado: spruce_ta.fjo((peb) => ({ moor: peb.moor, harbo: peb.harbo, ridge: peb.ridge, mesa: peb.mesa })),
}
